    Bug 2003051 - Make sure we wait for about3:pane and not about:blank in check3PaneState(). r=freaktechnik


    This was prompted by recent discussions in the CI channel indicating that some tests
    do not wait for the correct window to finish loading, and in some cases
    about:blank being fully loaded could incorrectly satisfy the loaded condition.

    Differential Revision: https://phabricator.services.mozilla.com/D274455

diff --git a/mail/components/extensions/test/browser/head.js b/mail/components/extensions/test/browser/head.js
index 53fbb691b97..16098420bc5 100644
--- a/mail/components/extensions/test/browser/head.js
+++ b/mail/components/extensions/test/browser/head.js
@@ -138,12 +138,11 @@ async function enforceState(state) {
 async function check3PaneState(folderPaneOpen = null, messagePaneOpen = null) {
   const tabmail = document.getElementById("tabmail");
   const tab = tabmail.currentTabInfo;
-  if (tab.chromeBrowser.contentDocument.readyState != "complete") {
-    await BrowserTestUtils.waitForEvent(
-      tab.chromeBrowser.contentWindow,
-      "load"
-    );
-  }
+  const doc = tab.chromeBrowser.contentDocument;
+
+  await TestUtils.waitForCondition(() => {
+    return doc.location.href == "about:3pane" && doc.readyState == "complete";
+  }, `The 3pane tab should be loaded`);

   const { paneLayout } = tabmail.currentAbout3Pane;
   if (folderPaneOpen !== null) {
